function trailsCard() {
  const c=G.active(state),visited=G.visitedRoutes(c);
  return `<section class="card trail-collection"><div class="section-heading"><h2>${esc(c.name)}の旅の手帖</h2><span>${visited.length}/4</span></div><p>最後まで歩いた道を、この子だけの記録に。</p><div class="trail-stamps">${Object.entries(G.ROUTES).map(([id,r])=>`<div class="trail-stamp ${visited.includes(id)?'visited':''}">${icon(r.icon)}<strong>${r.name}</strong><span>${visited.includes(id)?'歩いた道':'これからの道'}</span></div>`).join('')}</div><button class="button wide" data-view="explore">次のお出かけを考える</button></section>`;
}

function routeArt(id) {
  const colors={forest:['#dce9c8','#92b382','#547b50'],meadow:['#eef0c8','#bdd38d','#6e985c'],brook:['#deedf0','#a0c8b1','#567f65'],ridge:['#eee1d0','#baaf94','#777d66']};
  const [sky,hill,front]=colors[id];
  const detail=id==='brook'?'<path d="M100 28q-38 15 2 26t-25 27" stroke="#7fb1c0" stroke-width="18" fill="none"/>':id==='meadow'?'<g fill="#fff9d6"><circle cx="39" cy="57" r="4"/><circle cx="66" cy="65" r="4"/><circle cx="133" cy="54" r="4"/></g>':id==='ridge'?'<g fill="#fff9df"><circle cx="33" cy="14" r="3"/><circle cx="120" cy="13" r="2"/><path d="m153 15 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z"/></g>':'<path d="m32 56 14-35 14 35Zm78 1 15-43 16 43Z" fill="#466c43"/>';
  return `<svg viewBox="0 0 180 80" class="route-art" aria-hidden="true"><rect width="180" height="80" rx="12" fill="${sky}"/><path d="M0 59 34 23 76 56 117 28 180 62v18H0Z" fill="${hill}"/><path d="M0 72q47-26 95-7t85-6v21H0Z" fill="${front}"/>${detail}</svg>`;
}
function routesDialog() {
  const c=G.active(state),visited=G.visitedRoutes(c);
  modal('今日は、どの道を歩こう？',`<p>行き先を選ぶと出発します。1体につき全コース共通で1日1回。どの道も3場面、制限時間はありません。</p><div class="route-list">${Object.entries(G.ROUTES).map(([id,r])=>`<button class="route-option" data-route="${id}">${routeArt(id)}<span class="route-description"><strong>${r.name} ${visited.includes(id)?'<small>訪問ずみ</small>':''}</strong><span>${r.summary}</span><small>育つ力：${r.focus}</small></span><span aria-hidden="true">→</span></button>`).join('')}</div><p class="route-note">能力が足りない選択でも、おみやげと経験は残ります。選ぶ前に、この子の能力と結果の目安を確認できます。</p>`,'routes');
}
